"""Render Chinese evaluation using current English-report metrics."""
import json
from pathlib import Path
OUT=Path(__file__).resolve().parent/'results'/'translation_e2e_zh'
C=json.loads(r'''{"title":"\uc911\uad6d\uc5b4 \uc9c8\ubb38\u00b7\ub2f5\ubcc0 \ubc88\uc5ed \ud3c9\uac00 \uacb0\uacfc","summary":"\uc885\ud569 \uacb0\uacfc","qh":["ID","\uc911\uad6d\uc5b4 \uc9c8\ubb38","\uae30\uc900 \ud55c\uad6d\uc5b4","\uc2e4\uc81c \ud55c\uad6d\uc5b4 \ubc88\uc5ed","BLEU","BERTScore F1","\uc9c8\ubb38 \uc810\uc218"],"ah":["ID","\uc911\uad6d\uc5b4 \uc9c8\ubb38 / \uc804\uccb4 \ub2f5\ubcc0","BERTScore P","BERTScore R","BERTScore F1","\ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4 \uc810\uc218","70\uc810 \uc774\uc0c1"],"sh":["\uad6c\ubd84","\ud3c9\uade0 \uc810\uc218","\uae30\uc900 \uc774\uc0c1 \ubb38\ud56d"],"qname":"\uc9c8\ubb38 \ubc88\uc5ed","aname":"\ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4","qm":"\uc9c8\ubb38 \ubc88\uc5ed \uce21\uc815 \ubc29\uc2dd\uacfc \ucc44\ud0dd \uc774\uc720","am":"\ub2f5\ubcc0 \ubc88\uc5ed \uce21\uc815 \ubc29\uc2dd\uacfc \ucc44\ud0dd \uc774\uc720","qt":"\uc9c8\ubb38 \ubc88\uc5ed \uc804\uccb4 \uacb0\uacfc","at":"\ub2f5\ubcc0 \ubc88\uc5ed \uc804\uccb4 \uacb0\uacfc","yes":"\uc608","no":"\uc544\ub2c8\uc624","qtext":"\uc911\uad6d\uc5b4 \uac04\uccb4 \uc9c8\ubb38 20\uac1c\ub97c \uc11c\ube44\uc2a4\uac00 \ud55c\uad6d\uc5b4\ub85c \ubc88\uc5ed\ud55c \uacb0\uacfc\uc640, \uc0ac\uc6a9\uc790\uac00 \uc81c\uacf5\ud55c \ud55c\uad6d\uc5b4 \uae30\uc900 \ubb38\uc7a5\uc744 \ube44\uad50\ud588\uc2b5\ub2c8\ub2e4. \uc9c8\ubb38 \uc810\uc218 = BERTScore F1 \u00d7 100. \ud45c\ud604\uc774\ub098 \uc5b4\uc21c\uc774 \ub2ec\ub77c\ub3c4 \ube44\uc2b7\ud55c \ub73b\uc744 \ube44\uad50\ud558\uae30 \uc704\ud574 \ucc44\ud0dd\ud588\uc2b5\ub2c8\ub2e4. BLEU\ub294 \ubb38\uc790 \ub2e8\uc704 BLEU-4, exp smoothing, effective_order=True\ub85c \uacc4\uc0b0\ud55c \ud45c\ud604 \uc77c\uce58 \ubcf4\uc870 \uc9c0\ud45c\uc774\uba70 \uc810\uc218\uc5d0 \ud569\uc0b0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc911\uad6d\uc5b4 \uc9c8\ubb38\uc740 \uc601\uc5b4 \ub370\uc774\ud130\uc14b\uc758 \ub3d9\uc77c\ud55c 20\uac1c \uc8fc\uc81c\ub97c \uc2e4\ud589 \uc804\uc5d0 \uc911\uad6d\uc5b4\ub85c \uc791\uc131\ud588\uace0 \ud55c\uad6d\uc5b4 reference\ub294 \uadf8\ub300\ub85c \uc720\uc9c0\ud588\uc2b5\ub2c8\ub2e4. \uc911\uad6d\uc5b4 \uc9c8\ubb38\uc758 \uc6d0\uc5b4\ubbfc \ub3c5\ub9bd \uac80\uc218\ub294 \uc218\ud589\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.","atext":"\uac19\uc740 \uc2e4\uc81c \uc694\uccad\uc5d0\uc11c \uc0dd\uc131\ub41c \ud55c\uad6d\uc5b4 \ub2f5\ubcc0 \uc6d0\ubb38\uacfc \ucd5c\uc885 \uc911\uad6d\uc5b4 \ubc88\uc5ed\uc744 \ube44\uad50\ud588\uc2b5\ub2c8\ub2e4. \ub2f5\ubcc0 \ubc88\uc5ed \uc720\uc0ac\ub3c4 \uc810\uc218 = BERTScore F1 \u00d7 100. \uc608\ub97c \ub4e4\uc5b4 F1\uc774 0.72\uc774\uba74 72\uc810\uc785\ub2c8\ub2e4. P\ub294 \uc911\uad6d\uc5b4 \ub2f5\ubcc0\uc758 \ub2e8\uc5b4\uac00 \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uacfc \uc5bc\ub9c8\ub098 \uc798 \ub300\uc751\ud558\ub294\uc9c0, R\uc740 \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uc758 \ub2e8\uc5b4\uac00 \uc911\uad6d\uc5b4 \ub2f5\ubcc0\uacfc \uc5bc\ub9c8\ub098 \uc798 \ub300\uc751\ud558\ub294\uc9c0\ub97c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. F1\uc740 \ub450 \uac12\uc744 \ud568\uaed8 \ubc18\uc601\ud569\ub2c8\ub2e4. \ub450 \uc5b8\uc5b4\uc758 \ud45c\ud604\u00b7\uc5b4\uc21c \ucc28\uc774\ub97c \ub2e8\uc21c\ud55c \uae00\uc790 \uc77c\uce58\ubcf4\ub2e4 \uc720\uc5f0\ud558\uac8c \ube44\uad50\ud558\uace0, \uc784\uc758\uc758 \uc911\uad6d\uc5b4 \uc815\ub2f5 \ub2f5\ubcc0\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uae30 \uc704\ud574 \uc0ac\uc6a9\ud588\uc2b5\ub2c8\ub2e4. \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uc774 \uc5c6\ub294 \uc9c1\uc811 \uc751\ub2f5\uc740 N/A\ub85c \ucc98\ub9ac\ud558\uace0 \ubcc4\ub3c4\uc758 \uc6d0\ubb38\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","limit":"\ud55c\uad6d\uc5b4\uc640 \uc911\uad6d\uc5b4\ub97c \uc9c1\uc811 \ube44\uad50\ud55c BERTScore\ub294 \ud0d0\uc0c9\uc801 \ubb38\ub9e5 \uc720\uc0ac\ub3c4\uc785\ub2c8\ub2e4. \ubc88\uc5ed \uc815\ud655\ub3c4 \ubc31\ubd84\uc728\uc774\ub098 \uac80\uc99d\ub41c \ud569\uaca9 \ucc99\ub3c4\uac00 \uc544\ub2c8\uba70 \uc22b\uc790\u00b7\ud1b5\ud654\u00b7\ud589\uc815 \uc6a9\uc5b4 \uc624\uc5ed\uc744 \ub193\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc9c8\ubb38\uc740 \ud55c\uad6d\uc5b4\ub07c\ub9ac, \ub2f5\ubcc0\uc740 \ud55c\uad6d\uc5b4\uc640 \uc911\uad6d\uc5b4\ub97c \ube44\uad50\ud558\ubbc0\ub85c \ub450 \uc810\uc218\ub97c \ud569\uce5c \ub2e8\uc77c \uc885\ud569 \uc810\uc218\ub294 \uacc4\uc0b0\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub3d9\uc77c\ud55c \uc601\uc5b4 \ud3c9\uac00 \ubc29\uc2dd\uacfc \uc124\uc815\uc744 \uc0ac\uc6a9\ud588\uc9c0\ub9cc \uc5b8\uc5b4\ubcc4 \uc218\uce58\ub97c \uace7\ubc14\ub85c \uc815\ud655\ub3c4 \ucc28\uc774\ub85c \ud574\uc11d\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc810\uc218 \ud558\ud55c\u00b7\uac00\uc0b0\uc810\u00b7\ubb38\ud56d \uc81c\uc678\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.","settings":"\uacc4\uc0b0 \uc124\uc815: bert-base-multilingual-cased, layer 9, CPU, IDF \ubbf8\uc0ac\uc6a9, baseline rescaling \ubbf8\uc0ac\uc6a9. \uc2e4\uc81c \uc11c\ube44\uc2a4\uc758 NLLB \ubc88\uc5ed\uacfc LLM/RAG\ub97c \uadf8\ub300\ub85c \ud638\ucd9c\ud588\uc2b5\ub2c8\ub2e4. API \uc0ac\uc6a9\uc790 \uc5b8\uc5b4\ub294 zh\uc785\ub2c8\ub2e4. \ud504\ub85c\ud544 \ud654\uba74 \uc870\uc791 \uacb0\uacfc\uc640\ub294 \uad6c\ubd84\ub418\uba70 \uc2e4\uc81c \uc694\uccad\uc758 \uc5b8\uc5b4 \uc124\uc815\uc73c\ub85c \uc911\uad6d\uc5b4 \ucd9c\ub825\uc744 \uc120\ud0dd\ud588\uc2b5\ub2c8\ub2e4.","detail":"\ubb38\ud56d\ubcc4 \ud55c\uad6d\uc5b4 \uc6d0\ubb38\uacfc \uc2e4\uc81c \uc911\uad6d\uc5b4 \ub2f5\ubcc0","source":"\ud55c\uad6d\uc5b4 \ub2f5\ubcc0 \uc6d0\ubb38","target":"\uc2e4\uc81c \uc911\uad6d\uc5b4 \ub2f5\ubcc0","none":"\ud55c\uad6d\uc5b4 \ubc88\uc5ed \uc6d0\ubb38\uc774 \uc5c6\ub294 \uc9c1\uc811 \uc751\ub2f5","qdetails":"\uc9c8\ubb38","ref":"\uae30\uc900 \ud55c\uad6d\uc5b4","actual":"\uc2e4\uc81c \ud55c\uad6d\uc5b4 \ubc88\uc5ed"}''')
def render():
    d=json.loads((OUT/'results.json').read_text(encoding='utf-8'))
    rows=d['rows']; s=d['summary']
    def fmt(x,n=2): return 'N/A' if x is None else f'{x:.{n}f}'
    def table(h,rr):
        def cell(v): return str(v).replace('|',r'\|').replace('\n','<br>')
        return '\n'.join(['| '+' | '.join(h)+' |','| '+' | '.join(['---']*len(h))+' |']+['| '+' | '.join(cell(v) for v in r)+' |' for r in rr])
    summary=table(C['sh'],[[C['qname'],fmt(s['question_average']),str(s['question_above_80'])+'/20 (>=80)'],[C['aname'],fmt(s['answer_average']),str(s['answer_above_70'])+'/'+str(s['answer_evaluated_count'])+' (>=70)']])
    questions=table(C['qh'],[[r['id'],r['chinese_question'],r['reference'],r['system_translation'],fmt(r['smoothed_bleu']),fmt(r['bertscore'],4),fmt(r['question_semantic_score'])] for r in rows])
    answers=table(C['ah'],[[r['id'],f"[{r['chinese_question']}](details.md#item-{r['id']})",fmt(r.get('answer_precision'),4),fmt(r.get('answer_recall'),4),fmt(r.get('answer_f1'),4),fmt(r['answer_similarity_score']),'N/A' if r['answer_similarity_score'] is None else C['yes'] if r['answer_similarity_score']>=70 else C['no']] for r in rows])
    parts=['# '+C['title'],'## 1. '+C['summary'],summary,C['limit'],'## 2. '+C['qm'],C['qtext'],'## 3. '+C['qt'],questions,'## 4. '+C['am'],C['atext'],'## 5. '+C['at'],answers,'## 6. Settings / Reproduction',C['settings'],f"Answer token-limit (>512) IDs: {s['answer_over_token_limit_ids']}",'python evaluation/run_translation_chinese.py','[Actual results](results.json) | [Protocol](protocol.json) | [All answer pairs](details.md)','[BERTScore official implementation](https://github.com/Tiiiger/bert_score) | [Baseline explanation](https://github.com/Tiiiger/bert_score/blob/master/journal/rescale_baseline.md)']
    parts.insert(-3, '10\ubc88 \ud734\ud559\xb7\ubcf5\ud559 \ub2f5\ubcc0\uc740 \uc6d0\ubb38 \ub610\ub294 \ubc88\uc5ed\ubb38\uc774 \ubaa8\ub378\uc758 512\ud1a0\ud070 \ud55c\ub3c4\ub97c \ub118\uc5c8\uc2b5\ub2c8\ub2e4. BERTScore \uacc4\uc0b0\uc5d0\uc11c \ud574\ub2f9 \ubb38\ud56d\uc758 \ud6c4\ubc18 \ub0b4\uc6a9 \uc77c\ubd80\uac00 \uc81c\uc678\ub410\uc73c\ubbc0\ub85c 10\ubc88 \uc810\uc218\uc640 \uc804\uccb4 \ub2f5\ubcc0 \ud3c9\uade0\uc740 \uc774 \uc81c\ud55c\uc744 \ud3ec\ud568\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4.' if s['answer_over_token_limit_ids'] else '')
    text='\n\n'.join(parts)+'\n'
    assert '\ufffd' not in text
    assert len(questions.splitlines())==len(answers.splitlines())==22
    (OUT/'translation-report.md').write_text(text,encoding='utf-8')
    (OUT/'question-table.md').write_text(questions+'\n',encoding='utf-8')
    (OUT/'answer-table.md').write_text(answers+'\n',encoding='utf-8')
    detail=['# '+C['detail'],'','[Report](translation-report.md)','']
    for r in rows:
        detail += [f'<a id="item-{r["id"]}"></a>','',f'## {r["id"]}. {r["chinese_question"]}','',C['ref']+': '+r['reference'],'',C['actual']+': '+r['system_translation'],'','<details>','<summary>'+C['detail']+'</summary>','','### '+C['source'],'',r.get('korean_source_answer') or C['none'],'','### '+C['target'],'',r['chinese_final_answer'],'','</details>','']
    (OUT/'details.md').write_text('\n'.join(detail),encoding='utf-8')
    print('Chinese report validated: 20 question and answer rows.',flush=True)
if __name__=='__main__': render()

